<template>
  <WorkbenchShell role="cs" active="approvals" title="审批中心" subtitle="客服完成资料复核，资金类终审由具备权限的管理员处理并留痕">
    <template #actions><view class="permission-chip" :class="{active:canFinancialApprove}"><view/><text>{{ canFinancialApprove?'具备资金审批权限':'客服复核视图' }}</text></view></template>
    <view class="summary-strip"><view><text>{{ refunds.length }}</text><text>待审批退款</text></view><view><text>{{ withdrawals.length }}</text><text>待审批提现</text></view><view><text>{{ canFinancialApprove?'可执行终审':'仅可查看与复核' }}</text><text>当前权限</text></view></view>
    <view class="tabs"><button :class="{active:tab==='refunds'}" @click="switchTab('refunds')">退款申请 <text>{{ refunds.length }}</text></button><button :class="{active:tab==='withdrawals'}" @click="switchTab('withdrawals')">提现申请 <text>{{ withdrawals.length }}</text></button></view>
    <view v-if="error" class="error-box"><view><text>审批数据加载失败</text><text>{{ error }}</text></view><button @click="load">重新加载</button></view>

    <template v-if="tab==='refunds'">
      <view v-if="refunds.length" class="approval-list"><view v-for="refund in refunds" :key="refund.refundId" class="approval-card"><view class="card-head"><view class="type-icon refund">退</view><view><text>{{ refund.orderNo }}</text><text>{{ refundStatusText(refund.status) }} · {{ refundTypeText(refund.type) }}</text></view><view class="amount"><text>退款金额</text><text>¥{{ fenToYuan(refund.amountFen) }}</text></view></view><view class="reason"><text>申请原因</text><text>{{ refund.reason||'未填写' }}</text></view><view class="audit-note"><text>处理说明</text><text>服务端会再次校验支付状态、可退款金额与追佣规则，操作结果进入审计日志。</text></view>
        <view v-if="canFinancialApprove" class="actions"><button class="reject-button" @click="openRefundReject(refund)">驳回申请</button><button class="approve-button" :disabled="busy" @click="doApproveRefund(refund)">同意退款</button></view><view v-else class="pending-permission"><text>已进入管理员终审队列</text><text>客服账号不能直接变更资金状态</text></view>
        <view v-if="rejectTarget?.refundId===refund.refundId" class="reject-panel"><textarea v-model="rejectReason" placeholder="填写明确的驳回原因（必填）"/><view><button @click="cancelRefundReject">取消</button><button class="danger" :disabled="busy" @click="doRejectRefund">确认驳回</button></view></view>
      </view></view>
      <view v-else-if="!error" class="empty"><view>退</view><text>暂无待审批退款</text><text>新的退款申请提交后会显示在这里</text></view>
    </template>

    <template v-else>
      <view v-if="!canFinancialApprove" class="permission-state"><view>锁</view><text>当前客服账号无提现审批权限</text><text>提现涉及真实资金，请使用管理员或财务审核账号在管理后台处理。</text></view>
      <view v-else-if="withdrawals.length" class="approval-list"><view v-for="withdrawal in withdrawals" :key="withdrawal._id||withdrawal.id" class="approval-card"><view class="card-head"><view class="type-icon withdraw">提</view><view><text>{{ withdrawal.workerName||withdrawal.workerId||'接单人员' }}</text><text>{{ maskPhone(withdrawal.phone) }} · 本周第 {{ withdrawal.applyCountWeek??'-' }} 次</text></view><view class="amount"><text>提现金额</text><text>¥{{ fenToYuan(withdrawal.amountFen) }}</text></view></view><view class="realname-row"><view><text>实名认证</text><text>{{ realnameStatusText(withdrawal.realnameStatus) }}</text></view><view><text>申请时间</text><text>{{ formatDateTime(withdrawal.createdAt) }}</text></view><view><text>状态</text><text>{{ withdrawalStatusText(withdrawal.status) }}</text></view></view><view class="actions"><button class="reject-button" @click="openRejectWithdrawal(withdrawal)">驳回并解冻</button><button class="approve-button" @click="openPay(withdrawal)">确认实际打款</button></view>
        <view v-if="payTarget&&(payTarget._id||payTarget.id)===(withdrawal._id||withdrawal.id)" class="action-panel"><label><text>打款凭证号</text><input v-model="batchNo" placeholder="请输入银行/微信打款流水号"/></label><text>确认前请在外部支付渠道核实收款人和金额。</text><view><button @click="cancelPay">取消</button><button class="approve-button" :disabled="busy" @click="doMarkPaid(withdrawal)">确认已打款</button></view></view>
        <view v-if="rejectWithdrawalTarget&&(rejectWithdrawalTarget._id||rejectWithdrawalTarget.id)===(withdrawal._id||withdrawal.id)" class="reject-panel"><textarea v-model="rejectWithdrawalReason" placeholder="填写驳回原因（必填，提交后资金解冻）"/><view><button @click="cancelRejectWithdrawal">取消</button><button class="danger" :disabled="busy" @click="doRejectWithdrawal(withdrawal)">确认驳回</button></view></view>
      </view></view>
      <view v-else-if="!error" class="empty"><view>提</view><text>暂无待审批提现</text><text>所有提现申请均已处理</text></view>
    </template>
  </WorkbenchShell>
</template>

<script setup>
import { computed, ref } from 'vue';import { onLoad } from '@dcloudio/uni-app';import { api } from '../../api.js';import { confirmAction,fenToYuan,getSession,guard,oid,realnameStatusText,refundStatusText,withdrawalStatusText } from '../../common.js';import { formatDateTime,maskPhone } from '../../utils/display.js';import WorkbenchShell from '../../components/WorkbenchShell.vue';
const tab=ref('refunds');const refunds=ref([]);const withdrawals=ref([]);const error=ref('');const busy=ref(false);const rejectTarget=ref(null);const rejectReason=ref('');const payTarget=ref(null);const batchNo=ref('');const rejectWithdrawalTarget=ref(null);const rejectWithdrawalReason=ref('');const currentRole=computed(()=>getSession().user?.role||'');const canFinancialApprove=computed(()=>['ADMIN','SUPER_ADMIN','FINANCE_REVIEWER'].includes(currentRole.value));
function pickRefund(order){const list=order.refunds||[];return(Array.isArray(list)&&list[0])||order.refund||{};}function refundTypeText(type){return {full:'全额退款',partial_progress:'服务进度退款',partial_output:'未达标差额退款'}[type]||type||'退款申请';}
async function loadRefunds(){const orders=await api.listOrders({status:'REFUNDING'});const details=await Promise.all((orders||[]).map((order)=>api.getOrder(oid(order)).catch(()=>order)));refunds.value=details.map((order)=>({order,refund:pickRefund(order)})).filter(({refund,order})=>(refund.status||order.refundStatus)==='PENDING_APPROVAL').map(({refund,order})=>({refundId:refund.id||refund._id||order.pendingRefundId,orderNo:order.orderNo,type:refund.type,amountFen:refund.amountFen,reason:refund.reason,status:refund.status||order.refundStatus}));}
async function loadWithdrawals(){if(!canFinancialApprove.value){withdrawals.value=[];return;}const list=await api.listWithdrawals();withdrawals.value=(Array.isArray(list)?list:[]).filter((item)=>['PENDING_REVIEW','REVIEWING','APPROVED','PAYING','PAY_FAILED'].includes(item.status));}
async function load(){error.value='';try{if(tab.value==='refunds')await loadRefunds();else await loadWithdrawals();}catch(e){error.value=e.message||'加载失败';}}
function switchTab(value){tab.value=value;error.value='';load();}function paidBy(){const{user}=getSession();return user.nickname||user.phone||user.id||'管理员';}function openRefundReject(item){rejectTarget.value=item;rejectReason.value='';}function cancelRefundReject(){rejectTarget.value=null;rejectReason.value='';}
async function doApproveRefund(item){const confirmed=await confirmAction({title:'确认同意退款',content:`订单 ${item.orderNo} 将退款 ¥${fenToYuan(item.amountFen)}，并按服务端规则追佣。`,confirmText:'确认退款',danger:true});if(!confirmed)return;busy.value=true;try{await api.approveRefund(item.refundId);uni.showToast({title:'已同意退款',icon:'success'});await load();}catch(e){uni.showToast({title:e.message||'操作失败',icon:'none'});}finally{busy.value=false;}}
async function doRejectRefund(){if(!rejectReason.value.trim()){uni.showToast({title:'请填写驳回原因',icon:'none'});return;}const confirmed=await confirmAction({title:'确认驳回退款',content:'驳回原因将对后续处理人员可见，并写入操作记录。',confirmText:'确认驳回',danger:true});if(!confirmed)return;busy.value=true;try{await api.rejectRefund(rejectTarget.value.refundId,rejectReason.value.trim());uni.showToast({title:'已驳回',icon:'success'});cancelRefundReject();await load();}catch(e){uni.showToast({title:e.message||'操作失败',icon:'none'});}finally{busy.value=false;}}
function openPay(item){payTarget.value=item;batchNo.value='';rejectWithdrawalTarget.value=null;}function cancelPay(){payTarget.value=null;batchNo.value='';}function openRejectWithdrawal(item){rejectWithdrawalTarget.value=item;rejectWithdrawalReason.value='';payTarget.value=null;}function cancelRejectWithdrawal(){rejectWithdrawalTarget.value=null;rejectWithdrawalReason.value='';}
async function doMarkPaid(item){if(!batchNo.value.trim()){uni.showToast({title:'请输入打款凭证号',icon:'none'});return;}const confirmed=await confirmAction({title:'确认已实际打款',content:`确认已向 ${item.workerName||item.workerId} 打款 ¥${fenToYuan(item.amountFen)}？此操作会扣减冻结余额。`,confirmText:'确认已打款',danger:true});if(!confirmed)return;busy.value=true;try{await api.markWithdrawalPaid(item._id||item.id,paidBy(),batchNo.value.trim());uni.showToast({title:'已标记打款',icon:'success'});cancelPay();await load();}catch(e){uni.showToast({title:e.message||'操作失败',icon:'none'});}finally{busy.value=false;}}
async function doRejectWithdrawal(item){if(!rejectWithdrawalReason.value.trim()){uni.showToast({title:'请填写驳回原因',icon:'none'});return;}const confirmed=await confirmAction({title:'确认驳回提现',content:'驳回后冻结金额将退回接单人员可用余额。',confirmText:'确认驳回',danger:true});if(!confirmed)return;busy.value=true;try{await api.rejectWithdrawal(item._id||item.id,rejectWithdrawalReason.value.trim());uni.showToast({title:'已驳回',icon:'success'});cancelRejectWithdrawal();await load();}catch(e){uni.showToast({title:e.message||'操作失败',icon:'none'});}finally{busy.value=false;}}
onLoad((query)=>{if(!guard(['CS']))return;if(query?.tab)tab.value=query.tab==='withdrawals'?'withdrawals':'refunds';load();});
</script>

<style lang="scss" scoped>
.permission-chip{height:36px;padding:0 12px;display:flex;align-items:center;gap:8px;color:#475467;font-size:12px;font-weight:600;background:#f2f4f7;border-radius:999px}.permission-chip>view{width:8px;height:8px;background:#98a2b3;border-radius:50%}.permission-chip.active{color:#027a48;background:#ecfdf3}.permission-chip.active>view{background:var(--es-success)}.summary-strip{margin-bottom:16px;display:grid;grid-template-columns:1fr 1fr 1.4fr;background:#fff;border:1px solid var(--es-border-soft);border-radius:12px}.summary-strip>view{padding:15px 18px;border-right:1px solid var(--es-border-soft)}.summary-strip>view:last-child{border-right:0}.summary-strip text{display:block}.summary-strip text:first-child{font-size:18px;font-weight:750}.summary-strip>view:last-child text:first-child{font-size:13px}.summary-strip text:last-child{margin-top:4px;color:var(--es-text-dim);font-size:10px}.tabs{margin-bottom:14px;display:flex;border-bottom:1px solid var(--es-border-soft)}.tabs button{width:auto;height:42px;margin:0 18px -1px 0;padding:0 4px;color:#667085;font-size:13px;line-height:42px;background:transparent;border-bottom:2px solid transparent;border-radius:0}.tabs button text{margin-left:6px;padding:2px 6px;font-size:10px;background:#f2f4f7;border-radius:999px}.tabs button.active{color:#4338ca;font-weight:700;border-bottom-color:var(--es-primary)}.error-box{margin-bottom:14px;padding:13px 15px;display:flex;align-items:center;justify-content:space-between;color:#b42318;background:#fef3f2;border:1px solid #fecdca;border-radius:10px}.error-box text{display:block;font-size:11px}.error-box text:first-child{font-size:13px;font-weight:700}.error-box button{width:auto;height:32px;margin:0;padding:0 12px;color:#b42318;font-size:11px;line-height:32px;background:#fff;border:1px solid #fda29b;border-radius:8px}
.approval-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.approval-card{padding:19px;background:#fff;border:1px solid var(--es-border-soft);border-radius:14px;box-shadow:var(--es-glow)}.card-head{display:flex;align-items:center;gap:11px}.type-icon{width:38px;height:38px;flex:none;display:flex;align-items:center;justify-content:center;color:#b42318;font-size:12px;font-weight:750;background:#fef3f2;border-radius:11px}.type-icon.withdraw{color:#4338ca;background:#eef0ff}.card-head>view:nth-child(2){min-width:0;flex:1}.card-head>view:nth-child(2) text{display:block}.card-head>view:nth-child(2) text:first-child{font-size:14px;font-weight:700}.card-head>view:nth-child(2) text:last-child{margin-top:4px;color:var(--es-text-dim);font-size:10px}.amount{text-align:right}.amount text{display:block}.amount text:first-child{color:var(--es-text-dim);font-size:10px}.amount text:last-child{margin-top:3px;color:#b42318;font-size:17px;font-weight:750}.reason,.audit-note{margin-top:14px;padding:11px 12px;background:#f8fafc;border-radius:9px}.reason text,.audit-note text{display:block}.reason text:first-child,.audit-note text:first-child{color:var(--es-text-dim);font-size:10px}.reason text:last-child,.audit-note text:last-child{margin-top:5px;font-size:12px;line-height:1.5}.audit-note{background:#fffaeb}.audit-note text:last-child{color:#854a0e;font-size:10px}.realname-row{margin-top:14px;display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.realname-row>view{padding:10px;background:#f8fafc;border-radius:8px}.realname-row text{display:block}.realname-row text:first-child{color:var(--es-text-dim);font-size:9px}.realname-row text:last-child{margin-top:4px;font-size:11px;font-weight:600}.actions{margin-top:15px;display:flex;justify-content:flex-end;gap:8px}.approve-button,.reject-button,.reject-panel button,.action-panel button{width:auto;height:36px;margin:0;padding:0 13px;font-size:11px;line-height:36px;border-radius:8px}.approve-button{color:#fff;font-weight:600;background:var(--es-primary)}.reject-button{color:#b42318;background:#fff;border:1px solid #fda29b}.pending-permission{margin-top:14px;padding-top:12px;border-top:1px solid var(--es-border-soft)}.pending-permission text{display:block;color:#475467;font-size:11px}.pending-permission text:first-child{font-weight:650}.pending-permission text:last-child{margin-top:3px;color:var(--es-text-dim);font-size:10px}.reject-panel,.action-panel{margin-top:13px;padding:12px;background:#fef3f2;border:1px solid #fecdca;border-radius:9px}.reject-panel textarea{width:100%;height:74px;padding:9px;color:var(--es-text);font-size:11px;background:#fff;border:1px solid #fda29b;border-radius:7px}.reject-panel>view,.action-panel>view{margin-top:8px;display:flex;justify-content:flex-end;gap:8px}.reject-panel button,.action-panel button{height:32px;color:#475467;line-height:32px;background:#fff;border:1px solid var(--es-border)}.reject-panel .danger{color:#fff;background:#d92d20;border-color:#d92d20}.action-panel{background:#eef0ff;border-color:#c7d7fe}.action-panel label>text{display:block;margin-bottom:6px;color:#344054;font-size:10px;font-weight:600}.action-panel input{height:36px;padding:0 10px;font-size:11px;background:#fff;border:1px solid #aeb4fd;border-radius:7px}.action-panel>text{display:block;margin-top:7px;color:#475467;font-size:10px}.action-panel .approve-button{height:32px;color:#fff;line-height:32px;background:var(--es-primary);border-color:var(--es-primary)}.permission-state,.empty{min-height:330px;display:flex;flex-direction:column;align-items:center;justify-content:center;color:var(--es-text-dim);background:#fff;border:1px solid var(--es-border-soft);border-radius:14px}.permission-state>view,.empty>view{width:58px;height:58px;display:flex;align-items:center;justify-content:center;color:var(--es-primary);font-size:13px;font-weight:700;background:#eef0ff;border-radius:19px}.permission-state text:nth-child(2),.empty text:nth-child(2){margin-top:14px;color:var(--es-text);font-size:14px;font-weight:700}.permission-state text:last-child,.empty text:last-child{max-width:440px;margin-top:6px;text-align:center;font-size:11px;line-height:1.6}
@media(max-width:950px){.approval-list{grid-template-columns:1fr}}@media(max-width:767px){.summary-strip{grid-template-columns:1fr 1fr}.summary-strip>view{padding:12px}.summary-strip>view:nth-child(2){border-right:0}.summary-strip>view:last-child{grid-column:1/-1;border-top:1px solid var(--es-border-soft)}.approval-card{padding:16px}.realname-row{grid-template-columns:1fr}.actions button{flex:1}.permission-chip{height:32px}}
</style>
